gold.schema_ddl:
CREATE TABLE magazzini (
    id SERIAL PRIMARY KEY,
    nome TEXT NOT NULL,
    indirizzo TEXT,
    stato TEXT NOT NULL CHECK (stato IN ('attivo', 'inattivo', 'in_manutenzione'))
);

CREATE TABLE spedizioni (
    id SERIAL PRIMARY KEY,
    magazzino_id INT NOT NULL REFERENCES magazzini(id),
    descrizione TEXT,
    stato TEXT NOT NULL CHECK (stato IN ('pianificata', 'in_transito', 'consegnata', 'annullata')),
    data_spedizione DATE
);
